#!/usr/bin/env python3"""Fix collapsed lines by line number."""from pathlib import Pathtarget = Path("bin/agent/prompts.py")lines = target.read_text(encoding="utf-8").splitlines(keepends=True)# Line 743 (0-indexed 742) is the collapsed _serialize_element line# It starts with "def _serialize_element" and contains "def _read_tree"# Replace it with properly formatted codeserialize_block = '''def _serialize_element(elem: ET.Element, indent: str = "") -> str:    """Serialize an Element to XML string with CDATA for value elements."""    parts: list[str] = []    tag = elem.tag    attrs = ""    for k, v in elem.attrib.items():        attrs += f' {k}="{v}"'    children = list(elem)    has_children = len(children) > 0    if tag == "value" and elem.text:        parts.append(f"{indent}<{tag}{attrs}><![CDATA[{elem.text}]]></{tag}>")        return "".join(parts)    if not has_children and (elem.text is None or not elem.text.strip()):        parts.append(f"{indent}<{tag}{attrs} />")    elif not has_children:        parts.append(f"{indent}<{tag}{attrs}>{elem.text or ''}</{tag}>")    else:        parts.append(f"{indent}<{tag}{attrs}>")        for child in children:            parts.append("\\n")            parts.append(_serialize_element(child, indent + "  "))        parts.append(f"\\n{indent}</{tag}>")    return "".join(parts)def _write_prompts_xml(tree: ET.ElementTree, target: Path) -> None:    """Write the prompts XML tree to target using CDATA for value elements."""    root = tree.getroot()    xml_str = '<?xml version="1.0" encoding="UTF-8"?>\\n'    xml_str += _serialize_element(root)    xml_str += "\\n"    target.write_text(xml_str, encoding="utf-8")def _read_tree(path: Path) -> ET.ElementTree:'''update_block = '''def update_base_prompts_from_xml(path: str | Path | None = None) -> Path:    """Read XML system values and write them back as hardcoded defaults here."""    target = Path(path).expanduser().resolve() if path else prompts_config_path()    if not target.exists():        raise FileNotFoundError(f"prompts_config.xml not found at {target}")    tree = _read_tree(target)    root = tree.getroot()    system, _project = _ensure_sections(root)    xml_prompts = _read_prompt_section(system)    if not xml_prompts:        return target    this_file = Path(__file__).resolve()    src_text = this_file.read_text(encoding="utf-8")    lines_list: list[str] = ["DEFAULT_SYSTEM_PROMPTS: Dict[str, str] = {"]    seen: set[str] = set()    for key in DEFAULT_SYSTEM_PROMPTS:        seen.add(key)        value = xml_prompts.get(key, DEFAULT_SYSTEM_PROMPTS[key])        lines_list.append(f"    {key!r}: {value!r},")    for key, value in xml_prompts.items():        if key in seen:            continue        lines_list.append(f"    {key!r}: {value!r},")    lines_list.append("}")    new_block = "\\n".join(lines_list)    pattern = re.compile(        r"DEFAULT_SYSTEM_PROMPTS:\\s*Dict\\[str,\\s*str\\]\\s*=\\s*\\{.*?\\n\\}",        re.DOTALL,    )    if not pattern.search(src_text):        raise RuntimeError("Could not locate DEFAULT_SYSTEM_PROMPTS dict in prompts.py source")    updated = pattern.sub(new_block, src_text, count=1)    this_file.write_text(updated, encoding="utf-8")    return targetdef read_prompts_config(path: str | Path | None = None) -> Dict[str, Dict[str, str]]:'''cli_block = '''    if "--update-base" in args:        print(update_base_prompts_from_xml())        return 0    if "--reset-system" in args:'''new_lines = []i = 0fixed = 0while i < len(lines):    line = lines[i]    stripped = line.lstrip()        # Fix 1: _serialize_element collapsed    if 'def _serialize_element' in stripped and 'def _read_tree' in stripped:        new_lines.append(serialize_block)        if not serialize_block.endswith('\n'):            new_lines.append('\n')        print(f"Fixed _serialize_element at line {i+1}")        fixed += 1        i += 1        continue        # Fix 2: update_base_prompts_from_xml collapsed    if 'def update_base_prompts_from_xml' in stripped and 'def read_prompts_config' in stripped:        new_lines.append(update_block)        if not update_block.endswith('\n'):            new_lines.append('\n')        print(f"Fixed update_base_prompts_from_xml at line {i+1}")        fixed += 1        i += 1        continue        # Fix 3: --update-base CLI collapsed    if '--update-base' in stripped and '--reset-system' in stripped and 'return 0' in stripped and stripped.count('\n') == 0:        new_lines.append(cli_block)        if not cli_block.endswith('\n'):            new_lines.append('\n')        print(f"Fixed --update-base CLI at line {i+1}")        fixed += 1        i += 1        continue        new_lines.append(line)    i += 1target.write_text("".join(new_lines), encoding="utf-8")print(f"Done. Fixed {fixed} blocks. Total lines now: {len(new_lines)}")